examples.setupTemplate:
val transport = remember {
    object : MonarchAiTransport {
        override fun stream(request: MonarchAiTransportRequest): Flow<MonarchAiStreamEvent> = flowOf(
            MonarchAiStreamEvent.TextDelta("You asked: " + request.messages.lastOrNull()?.text.orEmpty()),
            MonarchAiStreamEvent.Done(),
        )
    }
}
// Hold the conversation above the navigation so it survives moving between screens.
val conversation = rememberMonarchAiConversation(transport)
var open by rememberSaveable { mutableStateOf(true) }
var minimized by rememberSaveable { mutableStateOf(false) }

